    INSERT INTO stage_mcqs (question, options, correct_index, explanation) VALUES
    ('61: What is the most common cause of physiologic jaundice in newborns?', '["ABO incompatibility", "Immature UDP-glucuronosyltransferase enzyme and increased RBC turnover", "Biliary atresia", "Sepsis"]', 1, 'Physiologic jaundice peaks around day 3-4 and resolves by day 10-14. (Williams)'),
    ('62: Physiologic jaundice is characterized by an elevation of which type of bilirubin?', '["Conjugated (Direct)", "Unconjugated (Indirect)", "Both equally", "Neither"]', 1, 'Due to immature hepatic conjugation. (Beckmann)'),
    ('63: Pathologic jaundice is suggested if jaundice appears within the first:', '["24 hours of life", "3 days of life", "1 week of life", "2 weeks of life"]', 0, 'Jaundice in the first 24 hours is always pathologic (usually hemolysis or sepsis). (ACOG)'),
    ('64: A rising total bilirubin > 5 mg/dL/day or a direct bilirubin > 2 mg/dL suggests:', '["Breastfeeding jaundice", "Physiologic jaundice", "Pathologic jaundice", "Normal variation"]', 2, 'Requires urgent investigation. (Williams)'),
    ('65: Breastfeeding jaundice occurs in the first week of life due to:', '["Suboptimal milk intake leading to dehydration and increased enterohepatic circulation", "A factor in breast milk that inhibits conjugation", "Hemolysis", "Biliary obstruction"]', 0, 'Management is to increase breastfeeding frequency and lactation support. (Beckmann)'),
    ('66: Breast milk jaundice typically presents when?', '["First 24 hours", "Days 2-3", "After the first week (days 7-14)", "After 1 month"]', 2, 'Caused by factors in mature breast milk (e.g., beta-glucuronidase) that increase enterohepatic circulation. (Williams)'),
    ('67: The definitive treatment for severe hyperbilirubinemia approaching neurotoxic levels is:', '["Phototherapy", "Exchange transfusion", "IV fluids", "Phenobarbital"]', 1, 'Used when levels are dangerously high or rising rapidly despite phototherapy to prevent kernicterus. (ACOG)'),
    ('68: How does phototherapy treat unconjugated hyperbilirubinemia?', '["It conjugates the bilirubin in the skin", "It converts unconjugated bilirubin into water-soluble lumirubin, which is excreted without conjugation", "It destroys red blood cells", "It increases UDP-GT activity"]', 1, 'Structural photoisomerization allows excretion in bile and urine. (Williams)'),
    ('69: "Kernicterus" (Bilirubin Encephalopathy) occurs when unconjugated bilirubin deposits in the:', '["Liver", "Basal ganglia and brainstem nuclei", "Kidneys", "Lungs"]', 1, 'Causes severe, permanent neurologic damage (choreoathetoid cerebral palsy, sensorineural hearing loss). (Beckmann)'),
    ('70: Which of the following is a classic early sign of acute bilirubin encephalopathy?', '["Hypertonia and opisthotonos", "Lethargy, poor feeding, and hypotonia", "Seizures", "Coma"]', 1, 'Progresses later to hypertonia and high-pitched cry. (ACOG)'),
    ('71: ABO incompatibility causing hemolytic disease of the newborn typically occurs with which maternal/fetal blood types?', '["Mother O, Baby A or B", "Mother A, Baby O", "Mother AB, Baby B", "Mother Rh negative, Baby Rh positive"]', 0, 'Maternal anti-A and anti-B IgG antibodies cross the placenta. (Williams)'),
    ('72: Is ABO incompatibility generally more or less severe than Rh alloimmunization?', '["More severe", "Less severe", "Equally severe", "Causes different symptoms"]', 1, 'ABO incompatibility is common but usually causes mild to moderate hemolysis. (Beckmann)'),
    ('73: Which test confirms the presence of maternal antibodies on the fetal/neonatal red blood cells?', '["Indirect Coombs test", "Direct Antiglobulin Test (DAT / Direct Coombs)", "Kleihauer-Betke test", "Apt test"]', 1, 'Positive DAT in the newborn confirms antibody-mediated hemolysis. (ACOG)'),
    ('74: Biliary Atresia classically presents with:', '["Jaundice in the first 24 hours", "Prolonged unconjugated hyperbilirubinemia", "Jaundice at 2-8 weeks of life, acholic (pale) stools, and conjugated hyperbilirubinemia", "Hematemesis"]', 2, 'Requires urgent Kasai portoenterostomy before 8 weeks of life. (Williams)'),
    ('75: Neonatal Hypoglycemia is generally defined as a blood glucose less than:', '["80 mg/dL", "60 mg/dL", "40-45 mg/dL", "20 mg/dL"]', 2, 'Thresholds vary, but < 40-45 in the first 24 hours warrants intervention. (ACOG/AAP)'),
    ('76: Infants of Diabetic Mothers (IDM) are at high risk for hypoglycemia immediately after birth due to:', '["Maternal insulin crossing the placenta", "Fetal hyperinsulinemia in response to chronic maternal hyperglycemia", "Defective gluconeogenesis", "Sepsis"]', 1, 'When the maternal glucose supply is cut at the cord, the high fetal insulin causes rapid hypoglycemia. (Williams)'),
    ('77: Typical clinical signs of neonatal hypoglycemia include:', '["Jitters, tremors, lethargy, poor feeding, and seizures", "High fever, rash, tachycardia", "Copious drooling, cyanosis", "Hypertonia, opisthotonos"]', 0, 'Can also be asymptomatic. (Beckmann)'),
    ('78: Initial treatment for asymptomatic neonatal hypoglycemia (e.g., glucose 35 mg/dL) is:', '["Immediate IV D10W bolus", "Enteral feeding (breastfeed or formula) and recheck in 30 minutes", "Glucagon IM", "Observation"]', 1, 'Enteral feeding is first-line if the infant is asymptomatic and able to feed. (AAP)'),
    ('79: If an infant is symptomatic from hypoglycemia or glucose is very low (< 25 mg/dL), what is the treatment?', '["Enteral feeding", "IV dextrose bolus (D10W)", "Epinephrine", "Corticosteroids"]', 1, 'Requires rapid correction to prevent brain injury. (ACOG)'),
    ('80: Infants of Diabetic Mothers are also at increased risk for which hematologic abnormality?', '["Anemia", "Polycythemia", "Thrombocytopenia", "Leukemia"]', 1, 'Chronic fetal hypoxia from increased metabolic demand leads to increased EPO and RBC production. (Williams)'),
    ('81: Polycythemia in the newborn is defined as a venous hematocrit greater than:', '["45%", "55%", "65%", "75%"]', 2, 'Can lead to hyperviscosity syndrome. (Beckmann)'),
    ('82: Symptoms of hyperviscosity syndrome secondary to polycythemia include:', '["Plethora (ruddy/red color), lethargy, respiratory distress, and hypoglycemia", "Pallor, tachycardia, shock", "Jaundice only", "Fever"]', 0, 'Sludging of blood flow affects multiple organs. (Williams)'),
    ('83: What is the treatment for severe, symptomatic polycythemia?', '["Blood transfusion", "Partial exchange transfusion (removing blood and replacing with normal saline)", "Diuretics", "Iron supplementation"]', 1, 'Dilutes the blood to lower the hematocrit. (ACOG)'),
    ('84: What is the most common organism causing Early-Onset Neonatal Sepsis (onset < 72 hours)?', '["E. coli", "Group B Streptococcus (GBS)", "Listeria monocytogenes", "Staphylococcus aureus"]', 1, 'GBS is the leading cause, followed closely by E. coli. (CDC/ACOG)'),
    ('85: Which maternal factor is a major risk for early-onset neonatal sepsis?', '["Gestational diabetes", "Prolonged rupture of membranes (> 18 hours)", "Advanced maternal age", "Oligohydramnios"]', 1, 'Allows ascending infection from the vaginal flora. (Beckmann)'),
    ('86: What is the classic empiric antibiotic regimen for suspected early-onset neonatal sepsis?', '["Ampicillin and Gentamicin", "Ceftriaxone and Azithromycin", "Vancomycin and Cefepime", "Penicillin alone"]', 0, 'Ampicillin covers GBS and Listeria; Gentamicin covers gram-negatives like E. coli. (ACOG)'),
    ('87: Listeria monocytogenes in the neonate classically causes:', '["Conjunctivitis", "Granulomatosis infantiseptica (disseminated abscesses/granulomas) and meningitis", "Heart block", "Cataracts"]', 1, 'Contracted from unpasteurized dairy or deli meats during pregnancy. (Williams)'),
    ('88: "Late-Onset" neonatal sepsis (> 72 hours) in the NICU is most commonly caused by:', '["GBS", "Coagulase-negative Staphylococci (e.g., S. epidermidis)", "E. coli", "Listeria"]', 1, 'Associated with indwelling catheters and prolonged hospitalization. (Beckmann)'),
    ('89: Neonatal meningitis most commonly presents with:', '["Nuchal rigidity (stiff neck)", "Fever, lethargy, poor feeding, bulging fontanelle", "Photophobia", "Kernig sign"]', 1, 'Classic meningeal signs (stiff neck, Kernig) are often ABSENT in neonates. (Williams)'),
    ('90: What procedure is mandatory if neonatal sepsis/meningitis is suspected (unless contraindicated by instability)?', '["CT scan of the head", "Lumbar Puncture", "EEG", "MRI"]', 1, 'To obtain CSF for cell count, glucose, protein, and culture. (ACOG)'),
    ('91: "Congenital Rubella Syndrome" classic triad?', '["Chorioretinitis, hydrocephalus, intracranial calcifications", "Sensorineural hearing loss, cataracts, patent ductus arteriosus (PDA)", "Microcephaly, seizures, rash", "Rhinitis, rash, skeletal abnormalities"]', 1, 'Also causes "blueberry muffin" rash (dermal erythropoiesis). (Williams)'),
    ('92: "Congenital Toxoplasmosis" classic triad?', '["Chorioretinitis, hydrocephalus, and diffuse intracranial calcifications", "Deafness, cataracts, PDA", "Skin scarring, limb hypoplasia", "Blueberry muffin rash, hepatosplenomegaly, microcephaly"]', 0, 'Contracted from cat feces or undercooked meat. (Beckmann)'),
    ('93: "Congenital Cytomegalovirus" (CMV) is the most common congenital infection. Classic findings?', '["Periventricular calcifications, microcephaly, sensorineural hearing loss, petechiae", "Diffuse calcifications, hydrocephalus", "Cataracts, PDA", "Bone lesions, snuffles"]', 0, 'Leading non-genetic cause of childhood hearing loss. (ACOG)'),
    ('94: "Congenital Syphilis" early signs (first 2 years) include:', '["Hutchinson teeth, saber shins", "Snuffles (syphilitic rhinitis), maculopapular rash on palms/soles, hepatosplenomegaly", "Cataracts, PDA", "Hydrocephalus, chorioretinitis"]', 1, 'Late signs (> 2 years) include Hutchinson teeth and saddle nose. (Williams)'),
    ('95: Treatment for a newborn with Congenital Syphilis?', '["Erythromycin", "Aqueous Crystalline Penicillin G IV for 10 days", "Ceftriaxone", "No treatment needed if asymptomatic"]', 1, 'All infants born to mothers with inadequate syphilis treatment must be evaluated and treated. (CDC/ACOG)'),
    ('96: "Congenital Varicella Syndrome" (infection < 20 weeks) classic presentation?', '["Cicatricial (zigzag) skin scarring, limb hypoplasia, cataracts", "Blueberry muffin rash", "Snuffles", "Hydrocephalus"]', 0, 'Risk is highest if mother gets chickenpox in the first or second trimester. (Williams)'),
    ('97: What should be given to a newborn if the mother develops Varicella 5 days before to 2 days after delivery?', '["Acyclovir", "Varicella Zoster Immune Globulin (VZIG)", "Varicella vaccine", "Nothing"]', 1, 'Neonatal varicella in this window is severe and can be fatal. (ACOG)'),
    ('98: Prevention of neonatal Herpes Simplex Virus (HSV) during delivery?', '["IV Acyclovir for the baby at birth", "Cesarean delivery if active genital lesions or prodromal symptoms are present", "Vaginal wash with Betadine", "Oral valacyclovir for baby"]', 1, 'Avoids direct contact with the virus in the birth canal. (ACOG)'),
    ('99: The three patterns of neonatal HSV infection are:', '["Skin-Eye-Mouth (SEM), CNS (meningoencephalitis), and Disseminated (multi-organ failure)", "Respiratory, GI, Renal", "Latent, Chronic, Acute", "Asymptomatic, Mild, Severe"]', 0, 'Treatment is IV Acyclovir for all forms. (Williams)'),
    ('100: "Blueberry Muffin" rash in a neonate represents:', '["Malignant melanoma", "Extramedullary hematopoiesis in the skin", "Petechiae from thrombocytopenia", "Allergic reaction"]', 1, 'Seen in CMV, Rubella, and sometimes Toxoplasmosis. (Beckmann)'),
    ('101: Neonatal Abstinence Syndrome (NAS) is primarily caused by maternal use of:', '["Cocaine", "Opiates (Heroin, Methadone, Buprenorphine)", "Marijuana", "Alcohol"]', 1, 'Withdrawal symptoms usually begin 24-72 hours after birth. (ACOG)'),
    ('102: Classic symptoms of Neonatal Abstinence Syndrome (Opiate withdrawal)?', '["Lethargy, hypotonia, sleepiness", "High-pitched cry, tremors, hyperactive reflexes, poor feeding, diarrhea, sneezing", "Seizures, microcephaly", "Blindness, deafness"]', 1, 'Scored using the Finnegan system. (Williams)'),
    ('103: First-line pharmacologic treatment for severe Neonatal Abstinence Syndrome (Opiate withdrawal)?', '["Naloxone", "Morphine or Methadone taper", "Phenobarbital", "Diazepam"]', 1, 'Naloxone is contraindicated as it precipitates acute withdrawal/seizures. (ACOG)'),
    ('104: Fetal Alcohol Syndrome (FAS) classic facial features?', '["Macrocephaly, prominent jaw", "Smooth philtrum, thin upper lip, short palpebral fissures", "Cleft lip/palate", "Large ears"]', 1, 'Also associated with growth restriction and intellectual disability. (Beckmann)'),
    ('105: Maternal Cocaine use during pregnancy is classically associated with which fetal complication?', '["Macrosomia", "Placental abruption, severe FGR, and microcephaly", "Congenital heart defects", "Cataracts"]', 1, 'Due to potent vasoconstriction. (Williams)'),
    ('106: "Omphalocele" is an abdominal wall defect where the bowel:', '["Herniates through the umbilicus and IS covered by a protective sac (peritoneum/amnion)", "Herniates to the right of the umbilicus with NO sac", "Stays inside the abdomen", "Herniates into the chest"]', 0, 'Often associated with other congenital anomalies and chromosomal syndromes (e.g., Trisomy 13, 18). (Beckmann)'),
    ('107: "Gastroschisis" is an abdominal wall defect where the bowel:', '["Herniates through the umbilicus in a sac", "Herniates through a defect typically to the RIGHT of the umbilicus with NO protective sac", "Is covered by skin", "Herniates into the scrotum"]', 1, 'Bowel is exposed to amniotic fluid, leading to inflammation/thickening. Usually NOT associated with chromosomal syndromes. (Williams)'),
    ('108: Which abdominal wall defect requires wrapping the exposed bowel in sterile saline/plastic immediately after birth to prevent fluid loss and infection?', '["Omphalocele", "Gastroschisis", "Umbilical hernia", "None"]', 1, 'The lack of a sac makes Gastroschisis an immediate management challenge for fluid loss. (ACOG)'),
    ('109: "Necrotizing Enterocolitis" (NEC) primarily affects which population?', '["Term infants", "Post-term infants", "Premature infants (especially extremely low birth weight)", "Infants of diabetic mothers"]', 2, 'Ischemic necrosis of the bowel wall. (Beckmann)'),
    ('110: The classic abdominal X-ray finding in Necrotizing Enterocolitis (NEC) is:', '["Pneumatosis intestinalis (air in the bowel wall)", "Air-fluid levels", "Double bubble sign", "Clear abdomen"]', 0, 'Can progress to portal venous gas and pneumoperitoneum (perforation). (Williams)'),
    ('111: Management of severe NEC with bowel perforation?', '["Oral antibiotics", "Immediate exploratory laparotomy and bowel resection", "Barium enema", "Observation"]', 1, 'Surgical emergency. (ACOG)'),
    ('112: "Duodenal Atresia" is strongly associated with which genetic condition?', '["Turner syndrome", "Down syndrome (Trisomy 21)", "Cystic Fibrosis", "Sickle Cell"]', 1, 'Presents with bilious vomiting on day 1. (Beckmann)'),
    ('113: The classic X-ray finding for Duodenal Atresia is:', '["Pneumatosis intestinalis", "Double bubble sign (air in stomach and proximal duodenum)", "Multiple air-fluid levels", "Free air under diaphragm"]', 1, 'The atresia prevents air from passing distally. (Williams)'),
    ('114: "Meconium Ileus" (failure to pass meconium, dilated bowel loops) is virtually pathognomonic for:', '["Down syndrome", "Cystic Fibrosis", "Hirschsprung disease", "Hypothyroidism"]', 1, 'Thick, inspissated meconium obstructs the terminal ileum. (Beckmann)'),
    ('115: "Hirschsprung Disease" (congenital aganglionic megacolon) presents with:', '["Bilious vomiting on day 1", "Failure to pass meconium in the first 48 hours, abdominal distension, and explosive stool after digital rectal exam", "Bloody diarrhea", "Jaundice"]', 1, 'Lack of ganglion cells in the distal colon prevents relaxation. (Williams)'),
    ('116: How is Hirschsprung Disease definitively diagnosed?', '["Barium enema", "Rectal suction biopsy showing absent ganglion cells", "CT scan", "Ultrasound"]', 1, 'A full-thickness or suction biopsy is required. (ACOG)'),
    ('117: Sudden Infant Death Syndrome (SIDS) risk is dramatically REDUCED by:', '["Prone positioning (on stomach)", "Supine positioning (on back) for sleep (''Back to Sleep'' campaign)", "Co-sleeping in the parent''s bed", "Using soft bedding"]', 1, 'The single most effective intervention to prevent SIDS. (AAP)'),
    ('118: Which of the following is considered a protective factor against SIDS?', '["Maternal smoking", "Pacifier use at nap/bedtime and breastfeeding", "Overheating the room", "Soft mattresses"]', 1, 'Both pacifier use and breastfeeding are associated with lower SIDS risk. (AAP)'),
    ('119: What is the normal weight loss for a term newborn in the first few days of life?', '["Up to 5%", "Up to 10%", "Up to 15%", "Up to 20%"]', 1, 'They should regain their birth weight by 10-14 days. (Beckmann)'),
    ('120: A neonate presents with copious drooling and episodes of choking/cyanosis during the first feeding. The nurse is unable to pass an orogastric tube into the stomach. Diagnosis?', '["Duodenal atresia", "Tracheoesophageal fistula / Esophageal atresia", "Choanal atresia", "Pyloric stenosis"]', 1, 'The tube coils in the blind esophageal pouch. (Williams)');
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation)
